fn find_index(items []string, target string) ?int {
    for i, item in items {
        if item == target {
            return i
        }
    }
    return none
}

fn main() {
    fruits := ['apple', 'pear', 'plum']
    a := find_index(fruits, 'pear') or { -1 }
    b := find_index(fruits, 'kiwi') or { -1 }
    println(a)
    println(b)
}

